  id:"q-gdhiv-007", banca:"Esc — Banco Didático", real:false, tipoProva:"graduacao", ano:2026, numeroNaProva:7,
  areaId:"area-cm", especialidadeId:"esp-infecto", assuntoId:"ass-hiv",
  enunciado:"Há um conjunto de estratégias de prevenção (biomédicas, comportamentais e estruturais) que, quando combinadas, constituem a chamada “prevenção combinada do HIV” ou “mandala de prevenção combinada”. A partir dessa informação, assinale a alternativa que apresenta uma estratégia de prevenção.",
  alternativas:[{id:"A",texto:"prevenir a transmissão vertical do HIV"},{id:"B",texto:"imunizar para hepatite B e sífilis"},{id:"C",texto:"tratar as pessoas vivendo com HIV/Aids a partir do momento em que apresentarem contagem de linfócitos T CD4 < 350 células/mm³"},{id:"D",texto:"substituir a profilaxia pré-exposição (PrEP) pela profilaxia pós-exposição"},{id:"E",texto:"usar profilaxia pós-exposição (pós-p) em até cinco dias após a exposição sexual desprotegida"}],
  gabarito:"A",
